-- READ/REPORT ONLY: collect every known activation prerequisite in one pass, not first-error-only.
-- Each independent inspection catches missing schema and reports BLOCK; errors never mean PASS.
-- CORRECTABLE is limited to the already approved four-row UK scope and P8 strategy corrections.
\set ON_ERROR_STOP on
BEGIN;
CREATE TEMP TABLE activation_checks(code text PRIMARY KEY,status text,detail jsonb) ON COMMIT DROP;
CREATE FUNCTION pg_temp.activation_check(p_code text,p_sql text,p_failure text DEFAULT 'BLOCK') RETURNS void LANGUAGE plpgsql AS $$
DECLARE r jsonb; BEGIN
  EXECUTE p_sql INTO r;
  INSERT INTO activation_checks VALUES(p_code,CASE WHEN (r->>'ok')::boolean THEN 'PASS' ELSE p_failure END,r->'detail');
EXCEPTION WHEN OTHERS THEN
  INSERT INTO activation_checks VALUES(p_code,'BLOCK',jsonb_build_object('sqlstate',SQLSTATE,'error',SQLERRM));
END $$;
SELECT pg_temp.activation_check('database', $q$ SELECT jsonb_build_object('ok',current_database()='movabi_develop','detail',current_database()) $q$);
SELECT pg_temp.activation_check('release2_referral', $q$ SELECT jsonb_build_object('ok',md5(replace(pg_get_functiondef('public.earn_referral(uuid,uuid)'::regprocedure),chr(13),''))='bbc10e72010059230652fd175f56a712','detail','exact release-2 earn_referral fingerprint required') $q$);
SELECT pg_temp.activation_check('release_functions', $q$ SELECT jsonb_build_object('ok',bool_and(to_regprocedure(signature) IS NOT NULL),'detail',jsonb_agg(jsonb_build_object('function',signature,'present',to_regprocedure(signature) IS NOT NULL))) FROM unnest(ARRAY['public.set_cancellation_policy_enabled(uuid,uuid,boolean)','public.publish_cancellation_policy(uuid,text,bigint,integer,integer,bigint,bigint,numeric,uuid)','public.wallet_currency_minor_exponent(text)','public.cancellation_fee_quote(uuid,text,timestamp with time zone)']) t(signature) $q$);
SELECT pg_temp.activation_check('gb_ride_minimum', $q$ SELECT jsonb_build_object('ok',count(DISTINCT minimum_fare)=1 AND min(minimum_fare)=3.35,'detail',coalesce(jsonb_agg(jsonb_build_object('id',id,'country',country_code,'minimum',minimum_fare)),'[]')) FROM public.pricing_config WHERE upper(country_code)='GB' AND currency_code='GBP' AND service_type='ride' AND is_active $q$);
-- A prior scope correction can be included in the same projected dry-run/apply transaction.
DO $$ BEGIN
  IF EXISTS(SELECT 1 FROM activation_checks WHERE code='gb_ride_minimum' AND status='BLOCK') THEN
    PERFORM pg_temp.activation_check('legacy_pricing_scope', $q$ SELECT jsonb_build_object('ok',count(*)=4 AND count(DISTINCT service_type)=4 AND min(minimum_fare) FILTER(WHERE service_type='ride')=3.35,'detail',coalesce(jsonb_agg(jsonb_build_object('id',id,'service',service_type,'minimum',minimum_fare)),'[]')) FROM public.pricing_config WHERE nullif(btrim(country_code),'') IS NULL AND currency_code='GBP' AND is_active AND nullif(btrim(market_city),'') IS NULL AND nullif(btrim(zone_id),'') IS NULL AND service_type IN('ride','delivery','errand','van-moving') $q$);
    IF EXISTS(SELECT 1 FROM activation_checks WHERE code='legacy_pricing_scope' AND status='PASS') THEN
      UPDATE activation_checks SET status='CORRECTABLE' WHERE code='legacy_pricing_scope';
      UPDATE activation_checks SET status='CORRECTABLE' WHERE code='gb_ride_minimum';
    END IF;
  END IF;
END $$;
SELECT pg_temp.activation_check('gb_profiles', $q$ SELECT jsonb_build_object('ok',count(*) FILTER(WHERE role='customer')>0 AND count(*) FILTER(WHERE role='driver')>0,'detail',jsonb_build_object('customers',count(*) FILTER(WHERE role='customer'),'drivers',count(*) FILTER(WHERE role='driver'),'tenants',count(DISTINCT tenant_id))) FROM public.profiles WHERE tenant_id IS NOT NULL AND upper(coalesce(nullif(btrim(registration_country_code),''),nullif(btrim(country_code),''),''))='GB' AND role IN('customer','driver') $q$);
SELECT pg_temp.activation_check('four_gb_strategy_scopes', $q$ SELECT jsonb_build_object('ok',count(*)=4 AND count(DISTINCT service_type)=4 AND bool_and(country_code='GB' AND currency='GBP' AND service_type IN('ride','delivery','errand','van-moving') AND (market_city IS NULL OR nullif(btrim(market_city),'') IS NOT NULL) AND (vehicle_class IS NULL OR nullif(btrim(vehicle_class),'') IS NOT NULL)),'detail',coalesce(jsonb_agg(to_jsonb(s) ORDER BY service_type,id),'[]')) FROM public.market_pricing_strategies s WHERE upper(country_code)='GB' $q$);
SELECT pg_temp.activation_check('p8_strategy_overrides', $q$ SELECT jsonb_build_object('ok',coalesce(bool_and(maximum_surge_multiplier IS NOT DISTINCT FROM 1.5 AND normal_demand_multiplier IS NOT DISTINCT FROM 1.0 AND busy_multiplier IS NULL),false),'detail',coalesce(jsonb_agg(jsonb_build_object('id',id,'service',service_type,'cap',maximum_surge_multiplier,'normal',normal_demand_multiplier,'busy',busy_multiplier)),'[]')) FROM public.market_pricing_strategies WHERE upper(country_code)='GB' $q$,'CORRECTABLE');
SELECT pg_temp.activation_check('ai_market_shadow', $q$ SELECT jsonb_build_object('ok',coalesce(bool_and(shadow_mode_enabled),true),'detail',coalesce(jsonb_agg(jsonb_build_object('country',country_code,'ai',ai_pricing_enabled,'shadow',shadow_mode_enabled,'enabled',market_enabled)),'[]')) FROM public.pricing_markets WHERE upper(country_code)='GB' $q$);
SELECT pg_temp.activation_check('market_intelligence_shadow', $q$ SELECT jsonb_build_object('ok',coalesce((SELECT value NOT IN ('false'::jsonb,'"false"'::jsonb) FROM public.marketplace_settings WHERE tenant_id IS NULL AND key='market_pricing_shadow_mode' ORDER BY created_at LIMIT 1),true),'detail',coalesce((SELECT value FROM public.marketplace_settings WHERE tenant_id IS NULL AND key='market_pricing_shadow_mode' ORDER BY created_at LIMIT 1),'true'::jsonb)) $q$);
SELECT pg_temp.activation_check('settings_duplicates', $q$ SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(to_jsonb(d)),'[]')) FROM (SELECT tenant_id,key,count(*) n FROM public.marketplace_settings WHERE key IN('dynamic_pricing','smart_matching','completion_pin_policy','quote_tenant_binding','market_pricing_shadow_mode','market_pricing_enabled') GROUP BY tenant_id,key HAVING count(*)>1) d $q$);
SELECT pg_temp.activation_check('campaign_terms', $q$ WITH gb AS (SELECT DISTINCT tenant_id FROM public.profiles WHERE tenant_id IS NOT NULL AND role IN('customer','driver') AND upper(coalesce(nullif(btrim(registration_country_code),''),nullif(btrim(country_code),''),''))='GB'), conflicts AS (
 SELECT c.* FROM public.campaigns c JOIN gb USING(tenant_id) WHERE code IN('FIRST5GB','REFERGB') AND NOT ((
 market_code='GB' AND currency_code='GBP' AND service_slug='ride' AND funding_party='platform' AND budget_minor=50000 AND per_user_cap=1 AND stacking='exclusive' AND referral_reward_bps=500
 AND (valid_from IS NULL OR valid_from<=now()) AND (valid_until IS NULL OR valid_until>=now())
 AND CASE WHEN code='FIRST5GB' THEN kind='customer_discount' AND audience='customer' AND value_type='percent' AND value=5 AND qualification='{"firstBookingOnly":true,"max_discount_minor":500,"min_qualifying_fare_minor":800}'::jsonb
 ELSE kind='referral' AND audience='both' AND value_type IS NULL AND value IS NULL AND qualification='{"reward_cap_minor":500,"min_qualifying_fare_minor":800}'::jsonb END) IS TRUE))
 SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(to_jsonb(conflicts)),'[]')) FROM conflicts $q$);
SELECT pg_temp.activation_check('existing_policy_skip_branch', $q$ WITH gb AS (SELECT DISTINCT tenant_id FROM public.profiles WHERE tenant_id IS NOT NULL AND role IN('customer','driver') AND upper(coalesce(nullif(btrim(registration_country_code),''),nullif(btrim(country_code),''),''))='GB')
 SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(to_jsonb(c)),'[]')) FROM public.cancellation_policies c JOIN gb USING(tenant_id)
 WHERE market_code='GB' AND enabled AND fee_minor=300 AND fee_cap_minor=300 AND grace_seconds=120 AND driver_compensation_percent=80
 AND (reference_fare_minor IS DISTINCT FROM 335 OR debt_threshold_bps IS DISTINCT FROM 5000 OR debt_threshold_minor IS DISTINCT FROM (335::bigint*5000/10000) OR compensation_funding IS DISTINCT FROM 'on_collection') $q$);
SELECT pg_temp.activation_check('write_privileges', $q$ SELECT jsonb_build_object('ok',bool_and(has_table_privilege(current_user,t,'SELECT') AND has_table_privilege(current_user,t,'INSERT') AND has_table_privilege(current_user,t,'UPDATE')),'detail',jsonb_agg(jsonb_build_object('table',t,'select',has_table_privilege(current_user,t,'SELECT'),'insert',has_table_privilege(current_user,t,'INSERT'),'update',has_table_privilege(current_user,t,'UPDATE')))) FROM unnest(ARRAY['public.market_pricing_strategies','public.marketplace_settings','public.campaigns','public.cancellation_policies','public.audit_logs']) x(t) $q$);
SELECT pg_temp.activation_check('strategy_triggers', $q$ SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(jsonb_build_object('name',tgname,'definition',pg_get_triggerdef(oid),'mode',tgenabled)),'[]')) FROM pg_trigger WHERE tgrelid='public.market_pricing_strategies'::regclass AND NOT tgisinternal AND tgenabled<>'D' AND (tgtype::int & 2)=2 AND (tgtype::int & 16)=16 $q$);
SELECT pg_temp.activation_check('settings_shapes', $q$ WITH gb AS (SELECT DISTINCT tenant_id FROM public.profiles WHERE tenant_id IS NOT NULL AND role IN('customer','driver') AND upper(coalesce(nullif(btrim(registration_country_code),''),nullif(btrim(country_code),''),''))='GB') SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(jsonb_build_object('id',s.id,'tenant',s.tenant_id,'key',s.key,'value',s.value)),'[]')) FROM public.marketplace_settings s JOIN gb USING(tenant_id) WHERE key IN('dynamic_pricing','smart_matching','completion_pin_policy','quote_tenant_binding') AND (jsonb_typeof(value)<>'object' OR (value ? 'markets' AND jsonb_typeof(value->'markets')<>'object')) $q$);
SELECT pg_temp.activation_check('legacy_pricing_conflicts', $q$ WITH legacy AS(SELECT id,service_type FROM public.pricing_config WHERE nullif(btrim(country_code),'') IS NULL AND currency_code='GBP' AND is_active AND nullif(btrim(market_city),'') IS NULL AND nullif(btrim(zone_id),'') IS NULL AND service_type IN('ride','delivery','errand','van-moving')) SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(to_jsonb(p)),'[]')) FROM public.pricing_config p WHERE upper(btrim(country_code))='GB' AND nullif(btrim(market_city),'') IS NULL AND nullif(btrim(zone_id),'') IS NULL AND service_type IN(SELECT service_type FROM legacy) $q$);
SELECT pg_temp.activation_check('effective_existing_policy', $q$ WITH gb AS (SELECT DISTINCT tenant_id FROM public.profiles WHERE tenant_id IS NOT NULL AND role IN('customer','driver') AND upper(coalesce(nullif(btrim(registration_country_code),''),nullif(btrim(country_code),''),''))='GB'), skipped AS (
 SELECT g.tenant_id FROM gb g WHERE EXISTS(SELECT 1 FROM public.cancellation_policies c WHERE c.tenant_id=g.tenant_id AND market_code='GB' AND enabled AND fee_minor=300 AND fee_cap_minor=300 AND grace_seconds=120 AND driver_compensation_percent=80)), actual AS (
 SELECT g.tenant_id,to_jsonb(p) AS policy FROM skipped g CROSS JOIN LATERAL public.active_cancellation_policy(g.tenant_id,'GB') p WHERE NOT((p.id IS NOT NULL AND p.fee_minor=300 AND p.fee_cap_minor=300 AND p.grace_seconds=120 AND p.driver_compensation_percent=80 AND p.compensation_funding='on_collection' AND p.reference_fare_minor=335 AND p.debt_threshold_bps=5000 AND p.debt_threshold_minor=335::bigint*5000/10000) IS TRUE)) SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(to_jsonb(actual)),'[]')) FROM actual $q$);
SELECT pg_temp.activation_check('campaign_capacity', $q$ SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(jsonb_build_object('id',id,'tenant',tenant_id,'code',code,'budget',budget_minor,'spent',spent_minor,'usage_limit',usage_limit)),'[]')) FROM public.campaigns WHERE market_code='GB' AND code IN('FIRST5GB','REFERGB') AND (budget_minor>0 AND spent_minor>=budget_minor OR usage_limit IS NOT NULL) $q$,'INFO');
SELECT pg_temp.activation_check('platform_fallback_shapes', $q$ WITH gb AS(SELECT DISTINCT tenant_id FROM public.profiles WHERE tenant_id IS NOT NULL AND role IN('customer','driver') AND upper(coalesce(nullif(btrim(registration_country_code),''),nullif(btrim(country_code),''),''))='GB'), platform AS(SELECT DISTINCT ON(key) id,key,value FROM public.marketplace_settings WHERE tenant_id IS NULL AND key IN('completion_pin_policy','smart_matching','dynamic_pricing') ORDER BY key,created_at DESC)
 SELECT jsonb_build_object('ok',count(*)=0,'detail',coalesce(jsonb_agg(jsonb_build_object('tenant',g.tenant_id,'platform_id',p.id,'key',p.key,'value',p.value)),'[]')) FROM gb g CROSS JOIN platform p WHERE NOT EXISTS(SELECT 1 FROM public.marketplace_settings own WHERE own.tenant_id=g.tenant_id AND own.key=p.key) AND (jsonb_typeof(p.value)<>'object' OR (p.value ? 'markets' AND jsonb_typeof(p.value->'markets')<>'object')) $q$);
SELECT 'ACTIVATION_PREFLIGHT_JSON='||jsonb_build_object('checks',jsonb_agg(to_jsonb(c) ORDER BY code),'blocks',count(*) FILTER(WHERE status='BLOCK'),'correctable',count(*) FILTER(WHERE status='CORRECTABLE'))::text FROM activation_checks c;
ROLLBACK;
